function build(M) {
  const body = M.prism([[-1.3,0],[1.3,0],[1.5,0.3],[1.5,1.3],[-1.5,1.3],[-1.5,0.3]], -1.05, 1.05);
  const base = M.T(M.cyl(1, 0.3, 40, 0), {s:[1.3,1,0.9]});
  const flange = M.box(3, 0.2, 2.4, 1.3);
  const parts = [body, base, flange];
  const ribs = [];
  for (let i = -5; i <= 5; i++) {
    for (const z of [-1.1, 1.1]) ribs.push(M.box(0.08, 0.9, 0.12, 0.3, i * 0.25));
  }
  const ribMesh = M.merge(ribs.map((r, k) => M.T(r, {pos:[0,0,(k%2?1.1:-1.1)]})));
  const bolts = [];
  for (let i = 0; i < 6; i++) {
    const x = -1.3 + i * 0.52;
    for (const z of [-1.05, 1.05]) bolts.push(M.T(M.cyl(0.08, 0.08, 6, 1.5), {pos:[x,0,z]}));
  }
  for (const x of [-1.35, 1.35]) for (const z of [-0.5, 0.5]) bolts.push(M.T(M.cyl(0.08, 0.08, 6, 1.5), {pos:[x,0,z]}));
  const ring = M.T(M.torus(0.85, 0.05, 40, 8), {pos:[0,1.52,0]});
  const plug = M.T(M.cyl(0.12, 0.1, 6, -0.1), {pos:[0.4,0,0]});
  return [
    {material:"steel", look:"solid", mesh:M.merge(parts)},
    {material:"steel", look:"solid", mesh:ribMesh},
    {material:"dark_steel", look:"solid", mesh:M.merge(bolts.concat([plug]))},
    {material:"dark_steel", look:"solid", mesh:ring}
  ];
}

function build(M) {
  const shaft = [];
  shaft.push(M.T(M.cyl(0.13, 2.0, 32, -1.0), {rx: 90}));
  const journals = [];
  for (const z of [-0.85, 0.85, -0.45, 0.45]) {
    journals.push(M.T(M.cyl(0.17, 0.14, 32, -0.07), {pos: [0, 0, z], rx: 90}));
  }
  const pin = M.T(M.cyl(0.12, 0.36, 32, -0.18), {pos: [0, 0.35, 0], rx: 90});
  const webs = [], cw = [];
  for (const z of [-0.24, 0.24]) {
    webs.push(M.box(0.36, 0.6, 0.1, -0.12, 0), );
    webs[webs.length - 1] = M.T(webs[webs.length - 1], {pos: [0, 0, z]});
    const half = [];
    for (let i = 0; i <= 20; i++) {
      const a = Math.PI + Math.PI * i / 20;
      half.push([Math.cos(a) * 0.58, Math.sin(a) * 0.58]);
    }
    cw.push(M.T(M.extrude(half, 0.12), {pos: [0, 0, z], rx: -90}));
  }
  const pulley = M.T(M.torus(0.2, 0.04, 32, 10), {pos: [0, 0, 0.98], rx: 90});
  const flange = M.T(M.cyl(0.3, 0.06, 32, -0.03), {pos: [0, 0, -0.97], rx: 90});
  const bolts = [];
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3;
    bolts.push(M.T(M.cyl(0.03, 0.03, 12, 0), {pos: [Math.cos(a) * 0.2, Math.sin(a) * 0.2, -1.0], rx: -90}));
  }
  return [
    {material: "steel", look: "solid", mesh: M.merge(shaft.concat(journals, [pin]))},
    {material: "dark_steel", look: "solid", mesh: M.merge(webs.concat(cw, [flange]))},
    {material: "blue", look: "solid", mesh: pulley},
    {material: "gold", look: "solid", mesh: M.merge(bolts)}
  ];
}

function build(M) {
  const H = 2.6, y0 = -1.3;
  const shell = M.lathe([[0.72,0],[0.85,0],[0.85,H],[0.72,H]], 40);
  const fins = [];
  for (let i = 0; i < 10; i++) fins.push(M.T(M.torus(0.86, 0.06, 40, 8), {pos:[0, 0.35 + i*0.21, 0]}));
  const base = M.lathe([[0.72,0],[1.0,0],[1.0,0.18],[0.72,0.18]], 40);
  const top = M.lathe([[0.72,H-0.15],[1.0,H-0.15],[1.0,H],[0.72,H]], 40);
  const iron = M.T(M.merge([shell, base, top, ...fins]), {pos:[0, y0, 0]});
  const bore = M.T(M.tube(0.71, H, 40), {pos:[0, 0, 0]});
  const bolts = [];
  for (let k = 0; k < 4; k++) {
    const a = (k*90 + 45) * Math.PI/180;
    const x = Math.cos(a)*0.92, z = Math.sin(a)*0.92;
    bolts.push(M.cyl(0.05, 0.08, 12, y0 + H), M.cyl(0.05, 0.08, 12, y0 + 0.18 - 0.0));
    bolts[bolts.length-1] = M.T(bolts[bolts.length-1], {pos:[x,0,z]});
    bolts[bolts.length-2] = M.T(bolts[bolts.length-2], {pos:[x,0,z]});
  }
  return [
    {material:"dark_steel", look:"solid", mesh: iron},
    {material:"steel", look:"solid", mesh: bore},
    {material:"steel", look:"solid", mesh: M.merge(bolts)}
  ];
}

