  [0.6, 0.69, 0.78].forEach(y => rings.push(M.T(M.torus(0.695, 0.018, 48, 8), {pos:[0,y,0]})));
  const bosses = [];
  [-1, 1].forEach(s => bosses.push(M.T(M.cyl(0.18, 0.08, 32, 0), {pos:[0,0.3,s*0.6], rx: s>0?90:-90})));
  const hole = [];
  [-1, 1].forEach(s => hole.push(M.T(M.cyl(0.1, 0.02, 32, 0), {pos:[0,0.3,s*0.685], rx: s>0?90:-90})));
