}

function build(M) {
  const body = M.box(2.2, 0.55, 2.2, -0.4);
  const fins = [];
  for (let i = 0; i < 4; i++) fins.push(M.box(2.0, 0.05, 2.0, 0.15 + i * 0.001 - 0.0, 0));
  const cover = M.box(1.7, 0.2, 1.7, 0.15);
  const bolts = [];
  const n = 5;
  for (let i = 0; i < n; i++) {
    const t = -0.9 + i * 0.45;
    for (const [x, z] of [[t, 0.95], [t, -0.95], [0.95, t], [-0.95, t]]) {
      bolts.push(M.cyl(0.07, 0.08, 6, 0.15));
      bolts[bolts.length - 1] = M.T(bolts[bolts.length - 1], {pos: [x, 0, z]});
    }
  }
  const boss = M.cyl(0.22, 0.1, 32, 0.35);
  const hole = M.cyl(0.12, 0.02, 24, 0.45);
  const ports = [
    M.T(M.lathe([[0.18,0],[0.25,0],[0.25,0.12],[0.18,0.12]], 32), {pos: [1.1, -0.12, 0], rz: -90}),
    M.T(M.lathe([[0.18,0],[0.25,0],[0.25,0.12],[0.18,0.12]], 32), {pos: [-1.1, -0.12, 0], rz: 90})
  ];
  const portHoles = [
    M.T(M.cyl(0.18, 0.02, 24, 0), {pos: [1.21, -0.12, 0], rz: -90}),
    M.T(M.cyl(0.18, 0.02, 24, 0), {pos: [-1.21, -0.12, 0], rz: 90})
  ];
  const gasket = M.box(2.15, 0.04, 2.15, -0.4);
  return [
    {material: "steel", look: "solid", mesh: M.merge([body, cover, boss, ...ports])},
    {material: "dark_steel", look: "solid", mesh: M.merge([...bolts, hole, ...portHoles])},
    {material: "copper", look: "solid", mesh: gasket}
  ];
}

function build(M) {
  const head = M.lathe([[0,0],[0.19,0],[0.2,0.02],[0.19,0.04],[0.06,0.1],[0.035,0.14],[0,0.14]], 40);
  const stem = M.cyl(0.03, 0.44, 24, 0.12);
  const seat = M.T(M.torus(0.17, 0.012, 40, 8), {pos:[0,0.035,0]});
  const tip = M.cyl(0.036, 0.04, 24, 0.56);
  const springPts = [];
  const coils = [];
  const turns = 5, steps = 120, R = 0.09, y0 = 0.3, y1 = 0.5;
  let prev = null;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, a = t * turns * Math.PI * 2;
    const p = [R * Math.cos(a), y0 + (y1 - y0) * t, R * Math.sin(a)];
    if (prev) coils.push(M.pipe(prev, p, 0.012, 8));
    prev = p;
  }
  const retainer = M.lathe([[0.035,0.5],[0.11,0.5],[0.11,0.52],[0.06,0.54],[0.035,0.54]], 32);
  const seatWasher = M.cyl(0.105, 0.015, 32, 0.285);
  const keepers = M.cyl(0.04, 0.03, 16, 0.53);
  return [
    {material:"steel", look:"solid", mesh:M.merge([head, stem, tip])},
    {material:"blue", look:"solid", mesh:M.merge(coils)},
    {material:"dark_steel", look:"solid", mesh:M.merge([retainer, seatWasher, keepers, seat])}
  ].map(o => ({...o, mesh: M.T(o.mesh, {pos:[0,-0.3,0]})}));
}

function build(M) {
  const H = 0.6;
  const y0 = -H / 2;
  const head = M.lathe([[0,0],[0.2,0],[0.2,0.025],[0.16,0.045],[0.05,0.09],[0.03,0.12],[0,0.12]], 40);
  const stem = M.cyl(0.028, 0.44, 20, 0.1);
  const keeper = M.frustum(0.045, 0.06, 0.04, 24, 0.5);
  const tip = M.cyl(0.03, 0.06, 20, 0.54);
  const retainer = M.cyl(0.11, 0.025, 32, 0.47);
  const seat = M.torus(0.17, 0.012, 40, 8);
  const coils = [];
  const turns = 6, n = 120, r = 0.09, ya = 0.2, yb = 0.47;
  let prev = null;
  for (let i = 0; i <= n; i++) {
    const t = i / n, a = t * turns * Math.PI * 2;
    const p = [r * Math.cos(a), ya + (yb - ya) * t, r * Math.sin(a)];
    if (prev) coils.push(M.pipe(prev, p, 0.012, 8));
    prev = p;
  }
  const sh = m => M.T(m, {pos: [0, y0, 0]});
  return [
    {material: "dark_steel", look: "solid", mesh: sh(head)},
    {material: "copper", look: "solid", mesh: sh(M.T(seat, {pos: [0, 0.03, 0]}))},
    {material: "steel", look: "solid", mesh: sh(M.merge([stem, keeper, tip, retainer]))},
    {material: "steel", look: "solid", mesh: sh(M.merge(coils))}
  ];
}

function build(M) {
