  for (let i = 0; i < 5; i++) ceramic.push(M.T(M.torus(0.066, 0.012, 28, 8), {pos:[0, 0.47 + i*0.04, 0]}));
  ceramic.push(M.frustum(0.04, 0.03, 0.06, 24, 0.0));
  const hex = M.cyl(0.13, 0.12, 6, 0.26);
  const washer = M.cyl(0.11, 0.02, 32, 0.24);
  const thread = [M.cyl(0.07, 0.24, 24, 0.0)];
  for (let i = 0; i < 7; i++) thread.push(M.T(M.torus(0.07, 0.01, 24, 6), {pos:[0, 0.02 + i*0.032, 0]}));
  const shell = M.frustum(0.1, 0.075, 0.03, 32, 0.37);
  const tip = M.merge([M.cyl(0.018, 0.05, 16, 0.7), M.cyl(0.035, 0.05, 20, 0.75)]);
  const center = M.cyl(0.01, 0.04, 12, -0.04);
  const ground = M.merge([M.box(0.015, 0.06, 0.03, -0.055, 0.06), M.box(0.075, 0.015, 0.03, -0.07, 0.03)]);
  return [
    {material: "white", look: "solid", mesh: M.merge(ceramic)},
    {material: "steel", look: "solid", mesh: M.merge([hex, washer, shell, tip])},
    {material: "dark_steel", look: "solid", mesh: M.merge(thread)},
    {material: "copper", look: "solid", mesh: M.merge([center, ground])}
  ];
}

